import{_ as o,o as r,c as s,a5 as p}from"./chunks/framework.DJo0M80U.js";const _=JSON.parse('{"title":"props 对象本身是 响应式","description":"在 Vue 3 中，props 对象本身是 响应式 （reactive）的，但其 响应性是浅级的 （shallow），不会自动对嵌套对象做深度转换或跟踪。 1. props 的底层实现 Vue 会在内部对传入组件的 props 对象先做一次 shallowReactive()（再。","frontmatter":{"title":"props 对象本身是 响应式","date":"2026-08-11T00:00:00.000Z","categories":["Vue 系统教程"],"tags":["Vue","Vue3","前端","教程","OneNote","响应式与组合式 API"],"description":"在 Vue 3 中，props 对象本身是 响应式 （reactive）的，但其 响应性是浅级的 （shallow），不会自动对嵌套对象做深度转换或跟踪。 1. props 的底层实现 Vue 会在内部对传入组件的 props 对象先做一次 shallowReactive()（再。","sidebarWeight":134,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/f-vue/响应式问题/Prop.属性名传入composable失去响应/props 对象本身是 响应式.md"},"headers":[],"relativePath":"posts/Vue系统教程/03-响应式与组合式 API/Prop.属性名传入composable失去响应/props 对象本身是 响应式.md","filePath":"posts/Vue系统教程/03-响应式与组合式 API/Prop.属性名传入composable失去响应/props 对象本身是 响应式.md"}'),t={name:"posts/Vue系统教程/03-响应式与组合式 API/Prop.属性名传入composable失去响应/props 对象本身是 响应式.md"};function l(a,e,i,u,n,c){return r(),s("div",null,[...e[0]||(e[0]=[p('<div><h1 id="props-对象本身是-响应式" tabindex="-1">props 对象本身是 响应式 <a class="header-anchor" href="#props-对象本身是-响应式" aria-label="Permalink to &quot;props 对象本身是 响应式&quot;">​</a></h1><blockquote><p>本节目标：理解“props 对象本身是 响应式”的核心思路，并能把它用于实际开发或面试表达。 在 Vue 3 中，props 对象本身是 <strong>响应式</strong> （reactive）的，但其 <strong>响应性是浅级的</strong>（shallow），不会自动对嵌套对象做深度转换或跟踪。</p></blockquote><ol><li><strong>props 的底层实现</strong>****Vue 会在内部对传入组件的 props 对象先做一次 shallowReactive()（再包装上一层 shallowReadonly()），所以： <ul><li><strong>顶层属性</strong>（如 props.foo、props.bar）是响应式、可追踪变化的。</li><li><strong>嵌套对象</strong>（如 props.user = { name: &#39;Alice&#39; }）并不会被 Vue 再一次深度转换，因此对子属性的直接修改不会触发渲染更新，除非该对象本身在父组件里已经是响应式的。 <a href="https://piesdoc.com/docs/vue3/props/?utm_source=chatgpt.com" target="_blank" rel="noreferrer">piesdoc.com</a><a href="https://github.com/vuejs/docs/issues/849?utm_source=chatgpt.com" target="_blank" rel="noreferrer">GitHub</a></li></ul></li><li><strong>监听（watch）默认也是浅级</strong>****import { defineComponent, watch } from &#39;vue&#39;export default defineComponent({ props: { user: Object }, setup(props) { // 默认只会在 props.user 整个引用变化时触发 watch(() =&gt; props.user, (newVal, oldVal) =&gt; { console.log(&#39;user 引用变了&#39;) })// 若要深度监听嵌套字段，必须明确开启 deep watch(() =&gt; props.user, (newVal) =&gt; { console.log(&#39;user 内部属性也变了&#39;) }, { deep: true }) }}) <ul><li>不加 { deep: true } 时，只追踪顶层引用变化。</li><li>加上 { deep: true } 后，才会递归地监听所有子属性。</li></ul></li><li><strong>如果需要对子属性做响应</strong><ul><li>可以在父组件中把嵌套对象先用 reactive() 或 ref() 包装，再传入子组件；</li><li>或在子组件中对 props 做一次深度转换（如 toRefs(props.user) / reactive(props.user)），但要注意这样可能破坏单向数据流的原则。</li></ul></li></ol><p><strong>总结：</strong></p><ul><li><strong>Vue 3 的 props 是响应式的，但只对顶层属性做浅级响应</strong>；</li><li>对嵌套对象或数组的深度监听，需要手动开启 { deep: true } 或在父级自己构建深度响应式对象。</li></ul></div>',1)])])}const g=o(t,[["render",l]]);export{_ as __pageData,g as default};
